mapper.select:
select * from ( select m.ID, m.TWINING_DISC_CODE, m.MACHINE_CODE, m.STATUS, m.FACTORY_CODE, m.DATA_SOURCE, m.IS_DELETE, m.CREATE_BY, m.CREATE_TIME, m.UPDATE_BY, m.UPDATE_TIME, m.REMARK, d.TWINING_DISC_NAME, d.PRO_SIZE, d.SORT_TYPE, mi.MACHINE_NAME from T_GSQ_TWINING_DISC_MACHINE m left join T_GSQ_TWINING_DISC d on d.TWINING_DISC_CODE = m.TWINING_DISC_CODE and d.IS_DELETE = '0' left join T_GSQ_MACHINE_INFO mi on mi.MACHINE_CODE = m.MACHINE_CODE and mi.IS_DELETE = '0' where m.IS_DELETE = '0'
and INSTR(m.TWINING_DISC_CODE, #{twiningDiscCode}) > 0
and INSTR(m.MACHINE_CODE, #{machineCode}) > 0
and m.STATUS = #{status}
and m.FACTORY_CODE = #{factoryCode}
and m.DATA_SOURCE = #{dataSource}
order by m.CREATE_TIME desc
) t
order by ${orderStr}

select count(1)
from T_GSQ_TWINING_DISC_MACHINE
where IS_DELETE = '0'
  and TWINING_DISC_CODE = #{entity.twiningDiscCode}
  and MACHINE_CODE = #{entity.machineCode}

    and ID != #{entity.id}
